function mapSport(name) {
  if (!name) return null;
  const n = name.toLowerCase();
  if (n.includes('basketball')) return 'basketball';
  if (n.includes('soccer')) return 'soccer';
  if (n.includes('football')) return 'football';
  if (n.includes('baseball') || n.includes('softball')) return 'baseball';
  if (n.includes('golf')) return 'golf';
  if (n.includes('volleyball')) return 'volleyball';
  if (n.includes('tennis')) return 'tennis';
  if (n.includes('lacrosse')) return 'lacrosse';
  if (n.includes('swimming') || n.includes('swim')) return 'swimming';
  if (n.includes('track') || n.includes('field')) return 'track';
  return null;
}
function getSportKey() { return getSportKeys()[0] || mapSport((state.data.sportsChosen || [])[0]); }
function getMeta() { return SPORT_META[getSportKey()] || GENERIC_META; }
function hasLibrary() { return !!getSportKey(); }

/* assessment option helpers (consumed by FLOWS in script.js) */
function posOptions() { return getMeta().positions; }
function goalOptions() { return getMeta().goals; }
function skillOptions() { return getMeta().skills; }
// When two sports are chosen, offer the UNION of both sports' equipment so the
// secondary sport's drills aren't starved (e.g. a volleyball net for a hooper).
function equipOptions() {
  const keys = getSportKeys();
  if (keys.length <= 1) return getMeta().equipment;
  const seen = new Set(); const out = [];
  keys.forEach(k => metaFor(k).equipment.forEach(o => { if (!seen.has(o.v)) { seen.add(o.v); out.push(o); } }));
  return out.length ? out : getMeta().equipment;
}

/* per-sport variants (used for dual-sport assessment + report sections) */
function metaFor(key) { return SPORT_META[key] || GENERIC_META; }
function posOptionsFor(key) { return metaFor(key).positions; }
function goalOptionsFor(key) { return metaFor(key).goals; }
function skillOptionsFor(key) { return metaFor(key).skills; }
function posLabelFor(key, val) { const o = metaFor(key).positions.find(x => x.v === val); return o ? o.l : (val || 'Not sure'); }
function secondarySportKey() { return getSportKeys()[1] || null; }

