const BB_POS = {
  'Ball handling': ['guard', 'wing', 'unknown'],
  'Shooting': ['guard', 'wing', 'forward', 'unknown'],
  'Finishing': ['guard', 'wing', 'forward', 'center', 'unknown'],
  'Footwork': ['guard', 'wing', 'forward', 'center', 'unknown'],
  'Defense': ['guard', 'wing', 'forward', 'center', 'unknown'],
  'Rebounding': ['wing', 'forward', 'center', 'unknown'],
  'Passing': ['guard', 'wing', 'forward', 'unknown'],
  'Conditioning': ['guard', 'wing', 'forward', 'center', 'unknown'],
  'Live Play': ['guard', 'wing', 'forward', 'center', 'unknown']
};
function slug(s) { return s.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, ''); }
function bbEquip(t) {
  if (t.includes('jump_rope')) return ['jump_rope'];
  const eq = ['ball'];
  ['hoop', 'wall', 'cones', 'two_basketballs', 'tennis_ball', 'partner'].forEach(k => { if (t.includes(k)) eq.push(k); });
  return eq;
}
function bbDuration(c, d) {
  if (c === 'Conditioning') return 6;
  if (c === 'Footwork') return 7;
  if (c === 'Shooting' || c === 'Finishing') return 10;
  if (c === 'Live Play') return 14;
  return 8;
}
function expandBB(src) {
  const diff = { B: 'beginner', I: 'intermediate', A: 'advanced' }[src.d];
  const eq = bbEquip(src.t);
  const space = src.t.includes('space') ? 'full' : (eq.includes('hoop') ? 'half' : 'small');
  const inj = src.t.filter(x => ['impact', 'jumping', 'contact', 'sprinting'].includes(x));
  const age = src.d === 'B' ? [7, 18] : src.d === 'I' ? [10, 18] : [12, 18];
  return {
    id: 'basketball_' + slug(src.n), sport: 'basketball', drill_name: src.n,
    description: src.w, what_it_does: src.w, why_athletes_do_it: src.y,
    difficulty_level: diff, skill_category: src.c, positions: BB_POS[src.c] || ['unknown'],
    required_equipment: eq, space_required: space,
    recommended_age_min: age[0], recommended_age_max: age[1],
    injury_cautions: inj, estimated_duration_minutes: bbDuration(src.c, src.d),
    coaching_notes: src.y, progression_level: { B: 1, I: 2, A: 3 }[src.d],
    wallok: src.t.includes('wallok')
  };
}

