function expandGolf(src) {
  const diff = { B: 'beginner', I: 'intermediate', A: 'advanced' }[src.d];
  const area = src.area || 'Putting';
  return {
    id: 'golf_' + slug(src.n), sport: 'golf', drill_name: src.n,
    description: src.w, what_it_does: src.w, why_athletes_do_it: src.y,
    how_to: src.how, statistic: src.stat, pga: src.pga,
    mistakes: src.miss || [], benchmarks: src.bench || null, best_for: src.best || [],
    area: area, difficulty_level: diff, skill_category: src.c, positions: ['unknown'],
    required_equipment: [],
    space_required: (area === 'Approach' || area === 'Ball Striking' || area === 'Long Game') ? ((src.t && src.t.includes('full')) ? 'full' : 'half') : ((src.t && src.t.includes('half')) ? 'half' : 'small'),
    recommended_age_min: 7, recommended_age_max: 18, injury_cautions: [],
    estimated_duration_minutes: area === 'Putting' ? 10 : 12, coaching_notes: src.y,
    progression_level: { B: 1, I: 2, A: 3 }[src.d], wallok: false, supervision: false
  };
}

