function expandVB(src) {
  const diff = { B: 'beginner', I: 'intermediate', A: 'advanced' }[src.d];
  const age = src.age || (src.d === 'B' ? [8, 18] : src.d === 'I' ? [10, 18] : [12, 18]);
  return {
    id: 'volleyball_' + slug(src.n), sport: 'volleyball', drill_name: src.n,
    description: src.w, what_it_does: src.w, why_athletes_do_it: src.y,
    how_to: src.how, statistic: src.stat, safety: src.safety || '',
    mistakes: src.miss || [], benchmarks: src.bench || null, best_for: src.best || [],
    difficulty_level: diff, skill_category: src.c, area: src.area || '',
    positions: src.pos || ['unknown'], required_equipment: src.eq || [],
    space_required: src.sp || 'small',
    recommended_age_min: age[0], recommended_age_max: age[1],
    injury_cautions: src.inj || [], estimated_duration_minutes: src.min || 8,
    coaching_notes: src.cue || src.y, reps: src.reps || '',
    progression_level: { B: 1, I: 2, A: 3 }[src.d],
    wallok: !!src.wallok, supervision: !!src.sup
  };
}

