const DRILL_DB = BB_SRC.map(expandBB).concat(BB_ADD2_SRC.map(expandBB)).concat(BB_LIVE).concat(BB_LIVE2).concat(FB_SRC.map(expandFB)).concat(FB_ADD_SRC.map(expandFB)).concat(FB_ADD2_SRC.map(expandFB)).concat(FB_ADD3_SRC.map(expandFB)).concat(SC_ADD_SRC.map(expandSC)).concat(SC_SRC.map(expandSC)).concat(GOLF_SRC.map(expandGolf)).concat(VB_SRC.map(expandVB)).concat(VB_ADD_SRC.map(expandVB)).concat(TENNIS).concat(LACROSSE).concat(OTHER).concat(CROSS)
  // Imported drills (per-sport JSON → validated/seeded by scripts/import-drills.js).
  .concat((typeof IMPORTED_DRILLS !== 'undefined' ? IMPORTED_DRILLS : (typeof window !== 'undefined' && window.IMPORTED_DRILLS) || []));

// derive regression/progression options within each (sport, category)
(function linkProgressions() {
  const groups = {};
  DRILL_DB.forEach(d => { const k = d.sport + '|' + d.skill_category; (groups[k] = groups[k] || []).push(d); });
  Object.values(groups).forEach(list => {
    list.sort((a, b) => a.progression_level - b.progression_level);
    list.forEach((d, i) => {
      d.regression_option = i > 0 ? list[i - 1].drill_name : null;
      d.progression_option = i < list.length - 1 ? list[i + 1].drill_name : null;
    });
  });
})();

/* =========================================================
   4) Athlete profile + eligibility filter
   ========================================================= */
const DAY_COUNT = { '1-2 days': 2, '3-4 days': 4, '5-6 days': 5, 'Daily': 6 };
const MINUTES = { '20 min': 20, '30-40 min': 35, '45-60 min': 55, '60+ min': 70 };
const SPACE_ORDER = { none: 0, small: 1, half: 2, full: 3 };
const INJURY_BLOCK = ['high_impact', 'impact', 'sprinting', 'jumping', 'contact', 'heading'];

const BALL_SPORTS = ['basketball', 'soccer', 'football', 'baseball', 'volleyball', 'tennis'];
// All chosen sports that have a real drill library, main sport first.
function getSportKeys() {
  const chosen = (state.data.sportsChosen || []);
  const main = state.data.mainSport;
  const keys = [];
  // honor an explicit main-sport choice by putting it first
  const ordered = main ? [main].concat(chosen.filter(s => s !== main)) : chosen;
  ordered.forEach(name => { const k = mapSport(name); if (k && !keys.includes(k)) keys.push(k); });
  return keys;
}

// Deterministic struggle→skill mapper (no LLM): matches the free-text struggle
// box onto a sport's skill taxonomy via name-stems + a small synonym map.
const STRUGGLE_SYN = {
  'ball handling': ['dribble', 'handle', 'crossover', 'ball control'],
  'first touch': ['trap', 'control the ball', 'receiv', 'settle'],
  'dribbling': ['dribble', 'close control', 'beat a defender', 'take on'],
  'shooting': ['shoot', 'shot', 'jumper', 'form', 'strike', 'release'],
  'finishing': ['layup', 'lay-up', 'finish', 'at the rim', 'around the basket'],
  'passing': ['pass', 'assist', 'distribut', 'turnover'],
  'defending': ['defen', 'guard', 'slide', 'tackl', 'mark', 'on-ball'],
  'defense': ['defen', 'guard', 'slide', 'on-ball', 'stance'],
  'rebounding': ['rebound', 'box out', 'boxout'],
  'chipping': ['chip', 'chunk', 'around the green', 'short game', 'thin'],
  'putting': ['putt', 'lag', 'green speed', 'three-putt', '3-putt'],
  'serve': ['serve', 'toss', 'double fault'],
  'conditioning': ['tired', 'gas', 'stamina', 'endurance', 'winded', 'out of shape', 'late in'],
  'agility': ['agil', 'quick', 'change of direction', 'lateral', 'cut'],
  'speed': ['slow', 'speed', 'faster', 'sprint', 'acceleration', 'first step'],
  'footwork': ['footwork', 'feet', 'balance', 'pivot', 'base'],
};
function mapStruggleToSkills(text, skills) {
  const t = String(text || '').toLowerCase();
  if (!t || !skills || !skills.length) return [];
  const out = [];
  skills.forEach(skill => {
    const sk = String(skill).toLowerCase();
    const stem = sk.replace(/ing$|s$/, '');
    let hit = t.includes(sk) || (stem.length >= 4 && t.includes(stem));
    const syn = STRUGGLE_SYN[sk]; if (syn) hit = hit || syn.some(w => t.includes(w));
    if (hit) out.push(skill);
  });
  return out;
}

function profileFromData() {
  const d = state.data;
  const sportKeys = getSportKeys();
  const sportKey = sportKeys[0] || getSportKey();
  // A ball is only "assumed" for sports that use one — golf/track/swimming don't.
  const equip = new Set((d.equipment || []).concat(BALL_SPORTS.includes(sportKey) ? ['ball'] : []));
  // a baseball player is assumed to own a glove and bat, so core drills stay eligible
  if (sportKey === 'baseball') { equip.add('glove'); equip.add('bat'); }
  if (d.environment === 'Team practice') equip.add('partner');
  // Per-sport sub-profiles: each sport keeps its OWN position, level, weaknesses,
  // strengths, and goal so a dual-sport athlete is analyzed separately per sport.
  const perSport = {};
  sportKeys.forEach((k, i) => {
    if (i === 0) perSport[k] = {
      position: d.position || 'unknown', level: (d.skillLevel || 'Beginner').toLowerCase(),
      weaknesses: d.weaknesses || [], strengths: d.strengths || [], mainGoal: d.mainGoal || '', exp: d.experienceYears || ''
    };
    else perSport[k] = {
      position: d.position2 || 'unknown', level: (d.skillLevel2 || d.skillLevel || 'Beginner').toLowerCase(),
      weaknesses: d.weaknesses2 || [], strengths: d.strengths2 || [], mainGoal: d.mainGoal2 || '', exp: d.experienceYears2 || d.experienceYears || ''
    };
  });
  // Objective baseline → DERIVED weaknesses (augments the self-reported ones).
  // assessment.js loads before drills.js; guard in case it is absent.
  let weaknesses = (d.weaknesses || []).slice();
  let capBoost = null, capability = null, percentiles = null, priorities = null, baselineTested = 0;
  if (typeof assessBaseline === 'function') {
    const ba = assessBaseline(d);
    if (ba) {
      ba.derivedWeaknesses.forEach(w => { if (!weaknesses.includes(w)) weaknesses.push(w); });
      capBoost = ba.catBoost; capability = ba.capability; percentiles = ba.percentiles;
      priorities = ba.priorities; baselineTested = ba.tested;
      // general athletic gaps apply to every chosen sport's sub-profile
      sportKeys.forEach(k => {
        if (!perSport[k]) return;
        const ws = (perSport[k].weaknesses || []).slice();
        ba.derivedWeaknesses.forEach(w => { if (!ws.includes(w)) ws.push(w); });
        perSport[k].weaknesses = ws;
        perSport[k].capBoost = capBoost;
      });
    }
  }
  // Struggle→skill (deterministic): map the free-text struggle box onto THIS
  // sport's skill taxonomy and merge into the weaknesses that drive selection.
  if (d.struggleText) {
    mapStruggleToSkills(d.struggleText, (SPORT_META[sportKey] || {}).skills || []).forEach(s => {
      if (!weaknesses.includes(s)) weaknesses.push(s);
      const ps = perSport[sportKeys[0]]; if (ps && ps.weaknesses && !ps.weaknesses.includes(s)) ps.weaknesses.push(s);
    });
  }
  return {
    sport: sportKey, perSport,
    sports: sportKeys, mainSport: sportKeys[0] || null, secondarySport: sportKeys[1] || null,
    multiSport: sportKeys.length >= 2,
    sportMeta: state.data.sportMeta || {},   // per-sport season/weeks for the allocation engine
    age: Number(d.age) || 12, height: d.height, weight: d.weight, gender: d.gender,
    position: d.position || 'unknown', level: (d.skillLevel || 'Beginner').toLowerCase(),
    dominantFoot: d.dominantFoot || '', dominantHand: d.dominantHand || '',
    throwingHand: d.throwingHand || '', battingSide: d.battingSide || '', secondaryPosition: d.secondaryPosition || '',
    exp: d.experienceYears || '', mainGoal: d.mainGoal || '',
    weaknesses, strengths: d.strengths || [],
    capBoost, capability, percentiles, priorities, baselineTested,
    timeline: d.goalTimeline || 'this season', tryout: d.tryout || '',
    equip, partner: equip.has('partner'),
    space: d.space || 'half', environment: d.environment || '', competition: d.competitionLevel || '',
    dayCount: DAY_COUNT[d.availability] || 3, minutes: MINUTES[d.sessionMinutes] || 35,
    injury: ['Recurring', 'Currently recovering'].includes(d.injuryHistory),
    minorInjury: d.injuryHistory === 'Minor / past', injuryHistory: d.injuryHistory || 'None',
    // GATE 1 inputs: age/developmental readiness (LTAD). Talent never overrides this.
    growthSpurt: d.growthSpurt || 'unknown',
    dev: (typeof LTAD !== 'undefined'
      ? LTAD.deriveDevProfile(Number(d.age) || 12, LTAD.sexFromGender(d.gender), d.growthSpurt || 'unknown')
      : null),
    injuries: Array.isArray(d.injuries) ? d.injuries : []
  };
}

function passes(drill, p) {
  // NOTE: height & weight are intentionally never used to include/exclude a drill —
  // they only personalize wording.
  //
  // TWO ORTHOGONAL GATES. GATE 1 (age / developmental readiness) is a HARD
  // safety ceiling that runs FIRST and is NEVER relaxed by skill, severity,
  // priority, or talent. GATE 2 (per-skill difficulty band) is talent and only
  // selects rungs WITHIN the age-eligible pool.

  /* ---------- GATE 1: AGE / DEVELOPMENTAL READINESS (hard, talent-independent) ---------- */
  if (typeof LTAD !== 'undefined' && p.dev) {
    if (!LTAD.gate1(drill, { dev: p.dev, age: p.age, injuries: p.injuries, supervisionAvailable: p.supervisionAvailable })) return false;
  } else {
    // fallback if LTAD module is absent: keep the original age-range floor/ceiling
    if (p.age < drill.recommended_age_min || p.age > drill.recommended_age_max) return false;
  }
  // legacy injury + youth-heading safety (kept; complements Gate 1 contraindications)
  if (p.injury && drill.injury_cautions.some(c => INJURY_BLOCK.includes(c))) return false;
  if (drill.injury_cautions.includes('heading') && p.age < 12) return false;

  /* ---------- GATE 2: SKILL DIFFICULTY BAND (talent) ---------- */
  const allow = p.level === 'beginner' ? ['beginner'] : p.level === 'intermediate' ? ['beginner', 'intermediate'] : ['intermediate', 'advanced'];
  if (!allow.includes(drill.difficulty_level)) return false;
  if (SPACE_ORDER[drill.space_required] > (SPACE_ORDER[p.space] ?? 2)) return false;
  for (const eq of drill.required_equipment) {
    if (eq === 'ball') continue;
    if (eq === 'partner') { if (!p.partner && !(drill.wallok && p.equip.has('wall'))) return false; continue; }
    if (!p.equip.has(eq)) return false;
  }
  return true;
}

/* =========================================================
   5) Scoring — prioritize stated weaknesses + goal + position
   ========================================================= */
const CONF_FRIENDLY = /Form Shooting|One-Hand Form|Free Throw|Spot Shooting|Pound Dribble|Layup|Juggling|Tee Hitting|Inside-Foot|Ladder|Wall|Athletic Stance|Diamond Catch|Pinkies|Rapid Fire|10-Yard|Falling Start|Ball Security|Stance and Start|Cone Weave|Toe Taps|Two-Touch|Penalty Routine|Confidence Finishing|Passing Gates/i;
function scoreDrill(drill, p) {
  let s = 1; const reasons = []; const cat = drill.skill_category;
  if (p.mainGoal === cat) { s += 3.2; reasons.push(`matches your main goal of improving ${cat.toLowerCase()}`); }
  else if (drill.area && p.mainGoal === drill.area) { s += 2.4; reasons.push(`builds your ${drill.area.toLowerCase()}`); }   // broad-area goal (e.g. "Putting")
  if (p.mainGoal === 'Confidence' && CONF_FRIENDLY.test(drill.drill_name)) { s += 3.2; reasons.push('is a confidence-builder — simple, high-success reps'); }
  if (p.mainGoal === 'Tryout prep' && /Tryout Preparation|Conditioning|Defense|Defending|Finishing|Hitting|Fielding|Catching|Agility|Speed|Footwork|Route running|Tackling|Pressure|Short Putts|Serving|Serve Receive|Passing|Setting|Blocking|Digging|Approach Footwork|Court Movement/i.test(cat)) { s += 2.2; reasons.push('is a tryout-prep priority'); }
  if (p.weaknesses.includes(cat)) { s += 2.8; reasons.push(`directly targets your weakness in ${cat.toLowerCase()}`); }
  else if (drill.area && p.weaknesses.includes(drill.area)) { s += 2.6; reasons.push(`targets your ${drill.area.toLowerCase()}`); }
  else if (drill.best_for && p.weaknesses.some(w => drill.best_for.includes(w))) { s += 1.6; reasons.push('targets a weakness you flagged'); }
  // cross-cutting "Scoring" goal/weakness — scoring & scrambling games in any area
  const wantScore = p.mainGoal === 'Scoring' || p.weaknesses.includes('Scoring');
  if (wantScore && (cat === 'Scoring' || cat === 'Scrambling' || (drill.best_for || []).includes('Scoring') || (drill.best_for || []).includes('Scrambling'))) { s += 2.6; reasons.push('builds scoring and scrambling'); }
  if (drill.best_for && drill.best_for.includes(p.mainGoal)) s += 1.2;
  if (p.strengths.includes(cat)) { s += 0.4; }
  // Graded boost from objective baseline test gaps — bigger measured deficit → bigger boost.
  if (p.capBoost) {
    const b = p.capBoost[cat] || (drill.area && p.capBoost[drill.area]) || 0;
    if (b) { s += b; if (b >= 1 && !reasons.some(r => /weakness|measured gap/.test(r))) reasons.push(`addresses a measured gap in ${cat.toLowerCase()}`); }
  }
  // Novelty memory — gently de-prioritize drills used in recent sessions so plans stay fresh.
  if (p.recentIds && typeof p.recentIds.has === 'function' && p.recentIds.has(drill.id)) s -= 1.2;
  if (drill.positions.includes(p.position) && p.position !== 'unknown') { s += 1.6; reasons.push(`fits your position`); }
  const lv = { beginner: 'beginner', intermediate: 'intermediate', advanced: 'advanced' }[p.level];
  if (drill.difficulty_level === lv) { s += 1; reasons.push(`is safe for your ${p.level} level`); }
  if (p.level === 'advanced' && drill.difficulty_level === 'beginner') s -= 1;
  if (p.mainGoal === 'Confidence' && drill.difficulty_level === 'advanced') s -= 4;
  return { d: drill, s, reasons };
}

