function benchmarkFor(cat, p) { return BENCH[cat] || 'Show measurable improvement from your week-1 baseline.'; }

/* =========================================================
   Multi-sport scoring + unified weekly schedule
   ========================================================= */
// Scored, eligible drills limited to one sport (or 'crossover').
// Uses that sport's OWN sub-profile (position/level/weaknesses/goal) when present.
function sportProfile(p, sportKey) {
  const ps = (p.perSport && p.perSport[sportKey]) || {};
  return {
    ...p, sport: sportKey,
    position: ps.position || p.position || 'unknown',
    level: ps.level || p.level,
    weaknesses: ps.weaknesses || p.weaknesses || [],
    strengths: ps.strengths || p.strengths || [],
    mainGoal: ps.mainGoal || p.mainGoal || ''
  };
}
function scoredForSport(p, sportKey) {
  const sp = sportKey === 'crossover' ? { ...p, sport: 'crossover' } : sportProfile(p, sportKey);
  const eligible = DRILL_DB.filter(d => d.sport === sportKey && passes(d, sp));
  return eligible.map(d => scoreDrill(d, sp)).sort((a, b) => b.s - a.s);
}
function sportLabelFor(key) {
  const map = { basketball: 'Basketball', soccer: 'Soccer', football: 'Football', baseball: 'Baseball', golf: 'Golf', volleyball: 'Volleyball' };
  return map[key] || cap(key);
}

// Lay out the week across sports without simply stacking two plans:
// main + secondary skill days, a shared crossover athletic day, and recovery.
/* =========================================================
   Multi-sport allocation bridge (allocate.js) — wired with smart
   defaults: priority = pick order (main sport first), season =
   off_season (no season captured yet). The engine decides base vs
   per-sport skill counts + day ordering; buildSession fills content.
   ========================================================= */
let _ALLOC = null;
function getAllocate() {
  if (_ALLOC) return _ALLOC;
  if (typeof Allocate !== 'undefined') _ALLOC = Allocate;
  else if (typeof window !== 'undefined' && window.Allocate) _ALLOC = window.Allocate;
  else if (typeof require === 'function') { try { _ALLOC = require('./allocate.js'); } catch (e) { _ALLOC = null; } }
  return _ALLOC;
}
function allocationFromProfile(p) {
  const A = getAllocate();
  if (!A) return null;
  const keys = (p.sports || []).slice(0, 3);
  if (keys.length < 2) return null;
  const main = p.sport || keys[0];
  const ordered = [main].concat(keys.filter(k => k !== main));   // priority = pick order, main = 1
  const meta = p.sportMeta || {};
  const sports = ordered.map((k, i) => {
    const m = meta[k] || {};
    const w = (m.weeks != null && m.weeks !== '') ? Number(m.weeks) : undefined;
    return {
      sportId: k, priorityRank: (i + 1),
      season: m.season || 'off_season',                          // captured, else smart default
      weeksToCompetition: (typeof w === 'number' && !isNaN(w)) ? w : undefined,
      sportMetrics: {}, struggleTags: p.weaknesses || [],
    };
  });
  const availability = {
    daysPerWeek: p.dayCount, sessionMinutes: p.minutes, age: p.age,
    level: p.level, injuries: p.injury ? ['general'] : [], equipment: [],
  };
  try { return A.allocate({ availability, sports }); } catch (e) { return null; }
}
// Allocation-driven day layout in the SAME shape multiSchedule returns
// ({type:'sport',sport} | {type:'cross'} | {type:'recovery'}); falls back cleanly.
function multiLayout(p, keys) {
  const A = getAllocate();
  const alloc = A ? allocationFromProfile(p) : null;
  if (!alloc) return { layout: multiSchedule(p.dayCount, keys), alloc: null };
  const train = A.scheduleWeek(alloc).filter(d => d.type !== 'rest');
  const layout = train.map(d => d.type === 'base' ? { type: 'cross' } : { type: 'sport', sport: d.sportId });
  // preserve a recovery day at higher volume (parity with the prior scheduler)
  if (alloc.baseSessions >= 2 && p.dayCount >= 5) {
    for (let i = layout.length - 1; i >= 0; i--) if (layout[i].type === 'cross') { layout[i] = { type: 'recovery' }; break; }
  }
  return { layout, alloc };
}

function multiSchedule(D, keys) {
  const [m, s] = keys;
  const days = [];
  const addSport = k => days.push({ type: 'sport', sport: k });
  if (D <= 2) { addSport(m); if (D === 2) addSport(s); return days; }
  addSport(m); addSport(s);
  days.push({ type: 'cross' });
  if (D >= 4) addSport(m);
  if (D >= 6) addSport(s);
  if (D >= 5) days.push({ type: 'recovery' });
  // pad any remainder with alternating sport days
  let t = 0;
  while (days.length < D) { addSport(t % 2 ? s : m); t++; }
  return days.slice(0, D);
}

function generateMultiSportPlan(p) {
  const keys = p.sports.slice(0, 3);
  const perSport = {}; keys.forEach(k => perSport[k] = scoredForSport(p, k));
  const cross = scoredForSport(p, 'crossover');
  if (cross.length) cross.forEach(x => { x.s += 1.2; });        // crossover is the unifier
  const haveEnough = keys.every(k => (perSport[k] || []).length >= 2) && cross.length >= 2;
  if (!haveEnough) return null;

  const ml = multiLayout(p, keys);
  const layout = ml.layout;
  const usedIds = new Set();
  const week = layout.map((spec, i) => {
    if (spec.type === 'cross') {
      const theme = (cross[0] && cross[0].d.skill_category) || 'Conditioning';
      return buildSession(theme, i, p, cross, { focusLabel: 'Shared Athletic Base', sportLabel: 'Both sports', crossover: true, usedIds });
    }
    if (spec.type === 'recovery') {
      const mob = cross.filter(x => ['Mobility', 'Core Stability'].includes(x.d.skill_category));
      const list = mob.length ? mob : cross;
      // recovery may REUSE drills (own set) so a small crossover pool already
      // spent on skill/base days never leaves the recovery day empty.
      return buildSession(list[0] ? list[0].d.skill_category : 'Mobility', i, p, list, { focusLabel: 'Recovery & Mobility', sportLabel: 'Recovery', recovery: true, capDelta: -2, usedIds: new Set() });
    }
    const scored = perSport[spec.sport] || [];
    const theme = focusCats(sportProfile(p, spec.sport), scored)[0] || (scored[0] && scored[0].d.skill_category) || 'Skill';
    return buildSession(theme, i, p, scored, { focusLabel: sportLabelFor(spec.sport) + ' — ' + theme, sportLabel: sportLabelFor(spec.sport), usedIds });
  });

  // merged focus tags for the report (sport priorities + crossover qualities)
  const focus = [];
  keys.forEach(k => focusCats(sportProfile(p, k), perSport[k]).slice(0, 2).forEach(c => focus.push(sportLabelFor(k) + ': ' + c)));
  cross.slice(0, 3).forEach(x => { const c = x.d.skill_category; if (!focus.includes('Crossover: ' + c)) focus.push('Crossover: ' + c); });
  const eligibleCount = keys.reduce((a, k) => a + (perSport[k] || []).length, 0) + cross.length;
  return { focus: focus.slice(0, 6), week, eligibleCount, multiSport: true, sports: keys.map(sportLabelFor), crossoverCount: cross.length, allocation: ml.alloc || null };
}

function generatePlan(p) {
  // Two or more sports → one unified, balanced program (not two stacked plans).
  if (p.multiSport && p.sports && p.sports.length >= 2) {
    const multi = generateMultiSportPlan(p);
    if (multi) return multi;          // else fall through to single-sport on the main sport
  }
  if (!p.sport) return null;
  const eligible = DRILL_DB.filter(d => d.sport === p.sport && passes(d, p));
  if (eligible.length < 3) return null;
  const scored = eligible.map(d => scoreDrill(d, p)).sort((a, b) => b.s - a.s);
  const focus = focusCats(p, scored);
  const themes = [];
  for (let i = 0; i < p.dayCount; i++) themes.push(focus[i % focus.length] || focus[0]);
  // Periodization: ramp volume across the 4-week block, then deload before the re-test.
  const per = periodize(p.weekInBlock);
  const week = themes.map((t, i) => buildSession(t, i, p, scored, { capDelta: per.capDelta, repNote: per.repNote }));
  return { focus, week, eligibleCount: eligible.length, phase: per.phase };
}

// 4-week block shape: build → build → peak → deload (before re-test). Defaults to
// Week 1 (base) when no block week is supplied, so a first-time plan is unchanged.
function periodize(weekInBlock) {
  const w = ((Number(weekInBlock) || 1) - 1) % 4; // 0..3
  if (w === 2) return { capDelta: 1, repNote: ' (+1 set / less rest)', phase: 'Peak' };
  if (w === 3) return { capDelta: -1, repNote: ' (lighter — deload before re-test)', phase: 'Deload' };
  if (w === 1) return { capDelta: 0, repNote: ' (add tempo)', phase: 'Build' };
  return { capDelta: 0, repNote: '', phase: 'Build' };
}

/* =========================================================
   Adaptive weekly engine — rebuilds next week from completion.
   stats = { pct, doneCats:{cat:n}, missedCats:{cat:n}, missedDrillIds:Set,
             doneDrillIds:Set, missedDrillNames:[], doneDrillNames:[] }
   Returns { plan, adaptation } where adaptation explains every change.
   ========================================================= */
// Difficulty ordering key — every drill carries a numeric progression_level (1–5);
// fall back to the difficulty band if it's ever missing.
function diffRank(d) {
  if (d && typeof d.progression_level === 'number') return d.progression_level;
  return ({ beginner: 2, intermediate: 3, advanced: 4 })[d && d.difficulty_level] || 3;
}
// Eligibility for a SWAP target = same checks as passes() MINUS the difficulty band
// (we deliberately want one step harder/easier than the athlete's nominal level).
// Tolerates a JSON-restored profile where p.equip is no longer a Set.
function swapOk(drill, p) {
  if (!p) return true;
  if (p.age != null && (p.age < drill.recommended_age_min || p.age > drill.recommended_age_max)) return false;
  if (typeof SPACE_ORDER !== 'undefined' && p.space != null &&
      SPACE_ORDER[drill.space_required] > (SPACE_ORDER[p.space] ?? 2)) return false;
  if (p.equip && typeof p.equip.has === 'function') {
    for (const eq of (drill.required_equipment || [])) {
      if (eq === 'ball') continue;
      if (eq === 'partner') { if (!p.partner && !(drill.wallok && p.equip.has('wall'))) return false; continue; }
      if (!p.equip.has(eq)) return false;
    }
  }
  if (p.injury && (drill.injury_cautions || []).some(c => INJURY_BLOCK.includes(c))) return false;
  if ((drill.injury_cautions || []).includes('heading') && p.age != null && p.age < 12) return false;
  return true;
}
// Nearest sibling in the SAME sport + skill at the next difficulty up (dir>0) or down.
function siblingDrill(d, dir, p) {
  if (!d || !d.sport || typeof DRILL_DB === 'undefined') return d;
  const rank = diffRank(d);
  const pool = DRILL_DB.filter(x =>
    x.sport === d.sport && x.skill_category === d.skill_category && x.id !== d.id &&
    (dir > 0 ? diffRank(x) > rank : diffRank(x) < rank) && swapOk(x, p));
  if (!pool.length) return d;
  pool.sort((a, b) => {
    const da = Math.abs(diffRank(a) - rank), db = Math.abs(diffRank(b) - rank);
    if (da !== db) return da - db;                                   // closest in difficulty
    const ta = Math.abs((a.estimated_duration_minutes || 8) - (d.estimated_duration_minutes || 8));
    const tb = Math.abs((b.estimated_duration_minutes || 8) - (d.estimated_duration_minutes || 8));
    if (ta !== tb) return ta - tb;                                   // keep session length stable
    return a.drill_name < b.drill_name ? -1 : 1;                     // deterministic tie-break
  });
  return pool[0];
}
function progressDrill(d, p) {               // harder sibling: explicit link, else nearest harder
  if (d && d.progression_option) {
    const next = DRILL_DB.find(x => x.sport === d.sport && x.drill_name === d.progression_option);
    if (next && swapOk(next, p)) return next;   // honor the link only if the athlete can do it
  }
  return siblingDrill(d, +1, p) || d;
}
function regressDrill(d, p) {                // easier sibling: explicit link, else nearest easier
  if (d && d.regression_option) {
    const prev = DRILL_DB.find(x => x.sport === d.sport && x.drill_name === d.regression_option);
    if (prev && swapOk(prev, p)) return prev;
  }
  return siblingDrill(d, -1, p) || d;
}

function adaptWeek(p, prevPlan, stats) {
  const pct = stats.pct;
  const direction = pct >= 85 ? 'increase' : pct < 50 ? 'decrease' : 'maintain';
  const changes = [];

  // Per-day intensity knobs — completion direction PLUS where we are in the
  // 4-week periodization block (build → peak → deload before re-test).
  const per = (typeof periodize === 'function') ? periodize(p.weekInBlock) : { capDelta: 0, repNote: '', phase: 'Build' };
  const capDelta = (direction === 'increase' ? 1 : direction === 'decrease' ? -1 : 0) + per.capDelta;
  const repNote = (direction === 'increase' ? ' (+1 set / less rest)' : direction === 'decrease' ? ' (shorter sets, full rest)' : '') + per.repNote;
  const intensityLabel = direction === 'increase' ? 'Increased' : direction === 'decrease' ? 'Reduced' : 'Maintained';

  // Re-derive the full eligible+scored pool the same way generatePlan does,
  // then BIAS it by what was missed/completed so next week truly adapts.
  const keys = (p.multiSport && p.sports && p.sports.length >= 2) ? p.sports.slice(0, 3) : [p.sport];
  const cross = (keys.length >= 2) ? scoredForSport(p, 'crossover') : [];

  const biasScored = (scored) => scored.map(x => {
    let s = x.s; const cat = x.d.skill_category;
    let d = x.d;
    if (stats.missedCats[cat]) { s += 3; }                            // repeat what was missed
    // Per-drill ACHIEVED quality drives progression more reliably than week %:
    // "too easy" → advance that exact drill; "too hard"/pain → make it easier.
    const wasEasy = !!(stats.easyIds && stats.easyIds.has(x.d.id));
    if (wasEasy) { d = progressDrill(d, p); s += 1.2; }
    else if ((stats.hardIds && stats.hardIds.has(x.d.id)) || (stats.painIds && stats.painIds.has(x.d.id))) { d = regressDrill(d, p); s -= 1; }
    else if (stats.doneDrillIds && stats.doneDrillIds.has(x.d.id)) {
      if (direction === 'increase') { d = progressDrill(d, p); s += 1; } // advance mastered drills
      else if (direction === 'decrease') s -= 1.5;                    // de-prioritize; make room
    }
    // overall de-load, but never undo a per-drill "too easy" progression
    if (direction === 'decrease' && !wasEasy) d = regressDrill(d, p);
    return { d, s, reasons: x.reasons };
  }).sort((a, b) => b.s - a.s);

  let plan;
  if (keys.length >= 2) {
    const perSport = {}; keys.forEach(k => perSport[k] = biasScored(scoredForSport(p, k)));
    const crossB = biasScored(cross);
    const ml = multiLayout(p, keys);
    const layout = ml.layout;
    const usedIds = new Set();
    const week = layout.map((spec, i) => {
      if (spec.type === 'cross') return buildSession((crossB[0] && crossB[0].d.skill_category) || 'Conditioning', i, p, crossB, { focusLabel: 'Shared Athletic Base', sportLabel: 'Both sports', crossover: true, usedIds, capDelta, repNote });
      if (spec.type === 'recovery') { const mob = crossB.filter(x => ['Mobility', 'Core Stability'].includes(x.d.skill_category)); const list = mob.length ? mob : crossB; return buildSession(list[0] ? list[0].d.skill_category : 'Mobility', i, p, list, { focusLabel: 'Recovery & Mobility', sportLabel: 'Recovery', recovery: true, capDelta: -2, usedIds: new Set() }); }
      const scored = perSport[spec.sport] || [];
      const theme = focusCats(sportProfile(p, spec.sport), scored)[0] || (scored[0] && scored[0].d.skill_category) || 'Skill';
      return buildSession(theme, i, p, scored, { focusLabel: sportLabelFor(spec.sport) + ' — ' + theme, sportLabel: sportLabelFor(spec.sport), usedIds, capDelta, repNote });
    });
    const focus = [];
    keys.forEach(k => focusCats(sportProfile(p, k), perSport[k]).slice(0, 2).forEach(c => focus.push(sportLabelFor(k) + ': ' + c)));
    plan = { focus: focus.slice(0, 6), week, eligibleCount: 0, multiSport: true, sports: keys.map(sportLabelFor), allocation: ml.alloc || null };
  } else {
    const scored = biasScored(scoredForSport(p, p.sport));
    if (scored.length < 3) return { plan: prevPlan, adaptation: { direction: 'maintain', changes: ['Kept your plan steady.'], intensityLabel: 'Maintained' } };
    const focus = focusCats(p, scored);
    const themes = []; for (let i = 0; i < p.dayCount; i++) themes.push(focus[i % focus.length] || focus[0]);
    const week = themes.map((t, i) => buildSession(t, i, p, scored, { capDelta, repNote }));
    plan = { focus, week, eligibleCount: scored.length };
  }

  // Human-readable change list (the "why").
  const missedTop = Object.keys(stats.missedCats).slice(0, 3);
  if (missedTop.length) changes.push(`Repeating missed work: ${missedTop.map(c => c.toLowerCase()).join(', ')}.`);
  if (direction === 'increase') changes.push('You completed most drills, so intensity steps up — advanced variations, an extra set, and shorter rest.');
  else if (direction === 'decrease') changes.push('Completion was low, so next week is simpler and shorter — easier variations and fewer drills per day to rebuild the habit.');
  else changes.push('Solid week — volume stays steady while we lock in consistency before adding load.');
  if (keys.length >= 2) changes.push('Crossover athletic work keeps both sports progressing without doubling your training time.');

  return { plan, adaptation: { direction, intensityLabel, changes, missedCats: missedTop } };
}

/* context for dashboard + report */
function drillCtx() {
  const p = profileFromData();
  const plan = generatePlan(p);
  const sportLabels = (p.sports || []).map(sportLabelFor);
  const multi = !!(plan && plan.multiSport);
  // For a unified plan the "focus" reads as a combined sport label.
  const focusLabel = multi ? sportLabels.join(' + ') : (sportLabels[0] || (state.data.sportsChosen || ['your sport'])[0]);
  return {
    path: 'sport', focus: focusLabel,
    secondary: multi ? sportLabels[1] : ((state.data.sportsChosen || [])[1] || null),
    multiSport: multi, sports: sportLabels, sportKeys: p.sports || [], perSport: p.perSport || {},
    level: cap(p.level), injury: p.injuryHistory, sessions: p.dayCount,
    duration: p.timeline, goals: [p.mainGoal || 'overall development'], age: p.age,
    drills: plan ? plan.week[0].drills.map(x => x.d.drill_name).slice(0, 4) : [],
    plan, profile: p, hasLibrary: !!plan
  };
}

/* =========================================================
   7) Render the full training plan (spec output format)
   ========================================================= */
const DIFF_LABEL = { beginner: 'Beginner', intermediate: 'Intermediate', advanced: 'Advanced' };
let _planLevel = 'beginner';   // set in renderDrillPlan so drill cards show the right benchmark

function drillBlock(item, dayIdx, n) {
  const d = item.d;
  const why = (item.reasons && item.reasons.length) ? 'it ' + item.reasons.slice(0, 2).join(', and ') : 'it rounds out a complete, balanced session';
  const prog = d.progression_option ? `Progress to: <em>${esc(d.progression_option)}</em>` : (d.regression_option ? `Easier option: <em>${esc(d.regression_option)}</em>` : 'Add reps or speed as it gets easier.');
  // extended fields (golf and any drill that carries them) — surfaced in the report
  const how = d.how_to ? `<p class="drillrow__how"><b>How:</b> ${esc(d.how_to)}</p>` : '';
  const stat = d.statistic ? `<p class="drillrow__stat"><b>Why it works:</b> ${esc(d.statistic)}</p>` : '';
  const pga = d.pga ? `<p class="drillrow__pga"><b>On tour:</b> ${esc(d.pga)}</p>` : '';
  const bmVal = d.benchmarks && d.benchmarks[_planLevel];
  const bm = bmVal ? `<p class="drillrow__bm"><b>Your goal (${esc(cap(_planLevel))}):</b> ${esc(bmVal)}</p>` : '';
  const miss = (d.mistakes && d.mistakes.length) ? `<p class="drillrow__miss"><b>Avoid:</b> ${esc(d.mistakes.join(' · '))}</p>` : '';
  const safe = d.safety ? `<p class="drillrow__safe"><b>Safety:</b> ${esc(d.safety)}</p>` : '';
  return `
    <div class="drillrow">
      <label class="drillrow__check"><input type="checkbox" disabled /><span></span></label>
      <div class="drillrow__body">
        <div class="drillrow__hd">
          <h5>${n}. ${esc(d.drill_name)}</h5>
          <span class="diffbadge diffbadge--${d.difficulty_level[0].toUpperCase()}">${DIFF_LABEL[d.difficulty_level]}</span>
        </div>
        <div class="drillrow__meta">
          <span>${esc(d.skill_category)}</span><span>·</span><span>${esc(item.sets)}</span><span>·</span><span>${d.estimated_duration_minutes} min</span>
        </div>
        ${how}
        <p class="drillrow__why"><b>Why chosen:</b> ${why}.</p>
        <p class="drillrow__focus"><b>Focus on:</b> ${esc(d.coaching_notes)}</p>
        ${stat}${pga}${bm}${miss}${safe}
        <p class="drillrow__prog">${prog}</p>
      </div>
    </div>`;
}

function dayCard(s) {
  const checklist = []
    .concat(s.warmup ? ['Completed warmup'] : [])
    .concat(s.drills.map(x => 'Completed ' + x.d.drill_name))
    .concat(s.cooldown ? ['Completed cooldown'] : []);
  return `
    <div class="daycard">
      <div class="daycard__hd">
        <span class="daycard__day">${esc(s.dayName)} · Day ${s.day}</span>
        <b>${esc(s.focus)}</b>
        <span class="daycard__time">~${s.total} min</span>
      </div>
      ${s.warmup ? `<p class="daycard__phase"><b>Warmup:</b> ${esc(s.warmup)}</p>` : ''}
      <div class="drillrows">${s.drills.map((x, i) => drillBlock(x, s.day, i + 1)).join('')}</div>
      ${s.cooldown ? `<p class="daycard__phase"><b>Cooldown:</b> ${esc(s.cooldown)}</p>` : ''}
      <div class="daycard__bench"><b>Progress benchmark:</b> ${esc(s.benchmark)}</div>
    </div>`;
}

function renderDrillPlan() {
  const ctx = drillCtx();
  const host = document.getElementById('planBody');
  const sportLabel = (state.data.sportsChosen || ['your sport'])[0];

  if (!ctx.plan) {
    host.innerHTML = `
      <div class="bp">
        <div class="bp__head"><h3>${esc(sportLabel)} Training Plan</h3><span>Library expanding</span></div>
        <div class="bp__section">
          <h4>Drill library coming soon for ${esc(sportLabel)}</h4>
          <p>Our structured drill database currently powers <strong>basketball, soccer, football, baseball/softball, golf, volleyball, tennis, and lacrosse</strong>. For ${esc(sportLabel)}, pick one of those as your focus sport, or check back as we add more — your assessment is saved.</p>
        </div>
      </div>`;
    return;
  }

  const p = ctx.profile, plan = ctx.plan;
  _planLevel = p.level;                  // drives per-drill benchmark display
  const meta = getMeta();
  const posL = (meta.positions.find(x => x.v === p.position) || {}).l || 'athlete';
  const posWord = p.position !== 'unknown' ? posL : 'player';
  const secL = getSportKey() === 'baseball' && p.secondaryPosition && p.secondaryPosition !== 'unknown'
    ? (meta.positions.find(x => x.v === p.secondaryPosition) || {}).l : '';
  const hand = (getSportKey() === 'baseball' && (p.throwingHand || p.battingSide))
    ? ` (${[p.throwingHand ? esc(p.throwingHand.toLowerCase()) + '-handed thrower' : '', p.battingSide ? 'bats ' + esc(p.battingSide.toLowerCase()) : ''].filter(Boolean).join(', ')})`
    : (getSportKey() === 'volleyball' && p.dominantHand && p.dominantHand !== 'Both')
      ? ` (${esc(p.dominantHand.toLowerCase())}-handed)`
      : '';
  const summary = `Based on your profile, you're a ${esc(p.age)}-year-old ${esc(sportLabel)} ${esc(posWord)}${secL ? ` / ${esc(secL)}` : ''}${p.dominantFoot ? ` (${esc(p.dominantFoot.toLowerCase())}-footed)` : ''}${hand} at a <strong>${esc(cap(p.level))}</strong> level`
    + `${p.mainGoal ? `, focused on <strong>${esc(p.mainGoal.toLowerCase())}</strong>` : ''}. `
    + `You can train <strong>${p.dayCount} day(s)/week</strong> for <strong>${p.minutes} minutes</strong> a session, working toward a ${esc(p.timeline)} goal.`;

  const injuryNote = p.injury
    ? `<div class="ai-note"><b>Injury-aware</b> High-impact and intense conditioning drills were filtered out. Keep movements pain-free and have a coach, parent, or physio review this plan.</div>`
    : p.minorInjury ? `<div class="ai-note"><b>Heads-up</b> You noted a minor/past injury — warm up fully and stop any drill that causes pain.</div>` : '';

  // ---- Safety notes (sport-aware) ----
  const sportKey = getSportKey();
  const supervised = plan.week.some(s => s.drills.some(x => x.d.supervision));
  const safety = [];
  if (sportKey === 'football') safety.push('Youth-safety first: this plan uses only non-contact technique, footwork, conditioning, and form drills. Do not add full-contact tackling or collision work without a qualified coach, proper equipment, and parent approval.');
  if (sportKey === 'soccer') safety.push('Heading is kept age-appropriate: heading drills are excluded under age 12, and we never program repeated heading volume. Follow your coach, parents, and local soccer guidance on heading.');
  if (sportKey === 'baseball') {
    safety.push('Arm care comes first: warm up before throwing, follow age-appropriate throwing and pitching limits, take rest days between high-volume throwing, and never throw through arm pain.');
    if (p.position === 'pitcher') safety.push('Young pitchers: avoid max-effort throwing every day and high pitch counts, and don’t add breaking balls without a qualified coach. Build velocity through mechanics and arm care, not overuse.');
    if (p.position === 'catcher') safety.push('Wear full catcher’s gear for receiving and blocking work, and build squat mobility gradually.');
  }
  if (sportKey === 'volleyball') {
    safety.push('Jump and land smart: warm up fully before hitting, blocking, and jump-training drills, land softly on two bent knees, and keep total jumping volume reasonable to protect the knees and ankles.');
    safety.push('Protect the shoulder: build serving and hitting volume gradually, and stop any swing or serve that causes shoulder pain.');
    if (['libero', 'ds'].includes(p.position)) safety.push('Floor-defense moves (sprawls, pancakes, rolls) should be learned on a forgiving surface with supervision before going full speed.');
  }
  if (supervised) {
    const what = sportKey === 'soccer' ? 'goalkeeper diving and heading drills' : sportKey === 'football' ? 'tackling-technique drills (slow-speed, no contact)' : sportKey === 'baseball' ? 'catching, blocking, longer-throw, and hard-hit reaction drills' : sportKey === 'volleyball' ? 'jump-training, swing-block, floor-defense, and live-attack drills' : 'higher-risk drills';
    safety.push(`Do the ${what} under qualified coach supervision with proper setup before going full speed.`);
  }
  if (p.injury) safety.push('You flagged an injury — get medical or coach clearance before progressing intensity.');
  const safetyNote = safety.length
    ? `<div class="bp__section bp__section--safety"><h4>Safety notes</h4><ul class="plan-list">${safety.map(x => `<li>${esc(x)}</li>`).join('')}</ul></div>` : '';

  const tag = arr => `<div class="bp__tags">${arr.map(x => `<span class="bp__tag">${esc(x)}</span>`).join('')}</div>`;

  host.innerHTML = `
    <div class="bp">
      <div class="bp__head">
        <h3>${esc(sportLabel)} Training Plan</h3>
        <span>${esc(cap(p.level))} · ${p.dayCount}×/week · ${plan.eligibleCount} drills matched</span>
      </div>

      <div class="bp__section"><h4>Athlete summary</h4><p>${summary}</p></div>
      <div class="bp__section"><h4>Main goal</h4><p><strong>${esc(p.mainGoal || 'Overall development')}</strong> · timeline: ${esc(p.timeline)}${p.tryout && p.tryout !== 'No tryout' ? ` · tryout ${esc(p.tryout.toLowerCase())}` : ''}</p></div>
      <div class="bp__section"><h4>Position focus</h4><p>Weighted toward a <strong>${esc(posL)}</strong>'s priorities${p.position === 'unknown' ? ' — pick a position later to sharpen this further' : ''}.</p></div>
      <div class="bp__section"><h4>Top weaknesses</h4>${p.weaknesses.length ? tag(p.weaknesses) : '<p>None selected.</p>'}</div>
      <div class="bp__section"><h4>Recommended training focus</h4><p>Selected from your library to attack your goal and weaknesses first:</p>${tag(plan.focus)}</div>

      ${injuryNote}
      ${safetyNote}

      <div class="bp__section">
        <h4>Week 1 plan <span class="muted">(every drill is from the library, matched to your answers)</span></h4>
        <div class="daycards">${plan.week.map(dayCard).join('')}</div>
      </div>

      <div class="bp__cta">
        <strong>Start training and track it weekly</strong>
        <span>Your dashboard turns this into checkable daily drills with streaks and AI coach reviews.</span>
        <div class="bp__price">
          <button type="button" class="btn btn--ghost" data-goresults>Download plan — ${esc(fmtMoney(PRICING.report))}</button>
          <button type="button" class="btn btn--solid" data-goresults>Membership — ${esc(fmtMoney(PRICING.monthly))}/mo</button>
        </div>
      </div>
    </div>`;

  // Grounded AI enrichment — writes a coach's note ABOUT the already-built
  // plan (cannot change drills). Async + optional: the plan is already complete.
  injectCoachNote(host, {
    sport: sportLabel,
    ageBand: ageBandLabel(p.age),
    level: cap(p.level),
    position: posL,
    goal: p.mainGoal || '',
    weaknesses: p.weaknesses || [],
    focus: plan.focus || [],
    drills: [...new Set([].concat(...plan.week.map(s => (s.drills || []).map(x => x.d && x.d.drill_name).filter(Boolean))))].slice(0, 12),
    days: p.dayCount, minutes: p.minutes, timeline: p.timeline,
  });
}

function ageBandLabel(age) { const a = Number(age) || 12; if (a <= 10) return '8-10'; if (a <= 13) return '11-13'; if (a <= 15) return '14-15'; return '16-18'; }

/* Serialize a real plan (DRILL_DB engine) into the PDF payload.
   With no args it reads the live results-screen plan (drillCtx); the dashboard
   passes its own (plan, profile, sportLabel) so the PDF matches the active week. */
function buildPdfPayload(planArg, profileArg, sportArg) {
  let plan, p, sportLabel;
  if (planArg && planArg.week && profileArg) {
    plan = planArg; p = profileArg;
    sportLabel = sportArg
      || (typeof sportLabelFor === 'function' && p.sports && p.sports[0] ? sportLabelFor(p.sports[0]) : (p.sports && p.sports[0]))
      || 'Training';
  } else {
    const ctx = (typeof drillCtx === 'function') ? drillCtx() : null;
    if (!ctx || !ctx.plan) return null;
    plan = ctx.plan; p = ctx.profile; sportLabel = (state.data.sportsChosen || ['your sport'])[0];
  }
  const meta = (typeof getMeta === 'function') ? getMeta() : { positions: [] };
  const posL = (meta.positions.find(x => x.v === p.position) || {}).l || (p.position && p.position !== 'unknown' ? cap(p.position) : '');
  const lvl = p.level;
  const days = (plan.week || []).map(s => ({
    day: s.day, name: s.dayName, focus: s.focus, totalMin: s.total,
    drills: (s.drills || []).map(x => ({
      name: x.d.drill_name, category: x.d.skill_category,
      difficulty: (DIFF_LABEL[x.d.difficulty_level] || x.d.difficulty_level || ''),
      durationMin: x.d.estimated_duration_minutes, sets: x.sets,
      howTo: x.d.how_to || '', statistic: x.d.statistic || '',
      coachingNotes: x.d.coaching_notes || '',
      benchmark: (x.d.benchmarks && x.d.benchmarks[lvl]) || '',
      progression: x.d.progression_option || '',
    })),
  }));
  const safety = [...document.querySelectorAll('.bp__section--safety li')].map(li => li.textContent.trim());
  const coachEl = document.querySelector('.bp__coach p');
  return {
    athlete: {
      sport: sportLabel, age: p.age, ageBand: ageBandLabel(p.age),
      level: cap(p.level), position: posL, goal: p.mainGoal || '',
      daysPerWeek: p.dayCount, minutes: p.minutes, timeline: p.timeline,
    },
    focus: plan.focus || [], weaknesses: p.weaknesses || [], days, safety,
    coachNote: coachEl ? coachEl.textContent.trim() : '',
  };
}

function _triggerDownload(blob, name) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}
async function downloadPlanPdf(btn, source) {
  const label = btn && btn.textContent; if (btn) { btn.disabled = true; btn.textContent = 'Preparing PDF…'; }
  const finish = () => { if (btn) { btn.disabled = false; btn.textContent = label; } };
  // Resolve the plan + profile to render from (no app state is mutated).
  let plan = source && source.plan, p = source && source.profile;
  if (!(plan && p)) { const ctx = (typeof drillCtx === 'function') ? drillCtx() : null; if (ctx) { plan = ctx.plan; p = ctx.profile; } }

  // 1) Themed plan-PDF via the isolated engine (renders + records in the DB).
  if (plan && p && window.PlanPdfMap && window.PlanPdfMap.fromPlanJson) {
    try {
      const doc = window.PlanPdfMap.fromPlanJson(plan, p, {
        labelFn: (typeof sportLabelFor === 'function') ? sportLabelFor : undefined,
        name: ((state.data && state.data.name) || '').trim(), weeks: 12,
      });
      const res = await fetch('/api/plan-pdf', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ doc }) });
      if (!res.ok) throw new Error('plan-pdf ' + res.status);
      const cd = res.headers.get('Content-Disposition') || '';
      const m = cd.match(/filename="(.+?)"/);
      _triggerDownload(await res.blob(), (m && m[1]) || 'Sporve-Plan.pdf');
      if (window.track) track('pdf_downloaded', { sport: doc.sportId, kind: 'themed' });
      finish(); return;
    } catch (e) { console.warn('[pdf] themed engine unavailable, falling back:', e && e.message); }
  }

  // 2) Fallback: original pdf-lib export — the download always works.
  const payload = (source && source.plan) ? buildPdfPayload(source.plan, source.profile, source.sport) : buildPdfPayload();
  if (!payload) { alert('Build a plan first, then download.'); finish(); return; }
  try {
    const res = await fetch('/api/report/pdf', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    if (!res.ok) throw new Error('pdf ' + res.status);
    _triggerDownload(await res.blob(), 'Sporve-' + String(payload.athlete.sport || 'Training').replace(/[^a-z0-9]+/gi, '-') + '-Plan.pdf');
    if (window.track) track('pdf_downloaded', { sport: payload.athlete.sport, kind: 'pdflib' });
  } catch (e) {
    console.error('[pdf] download failed', e);
    alert('Sorry — the PDF could not be generated. Please try again.');
  } finally { finish(); }
}
window.downloadPlanPdf = downloadPlanPdf;

// Inserts the grounded coach note just under the plan header when it returns.
function injectCoachNote(host, c) {
  if (!host || typeof window === 'undefined' || !(window.Athlon && Athlon.enrichPlan)) return;
  Athlon.enrichPlan(c).then(function (r) {
    if (!r || (!r.coachSummary && !r.parentNote)) return;
    const head = host.querySelector('.bp__head');
    if (!head || head.parentElement.querySelector('.bp__coach')) return;
    const div = document.createElement('div');
    div.className = 'bp__section bp__coach';
    div.innerHTML = '<h4>Coach’s note' + (r.source === 'ai' ? ' <span class="bp__ai">AI</span>' : '') + '</h4>'
      + (r.coachSummary ? '<p>' + esc(r.coachSummary) + '</p>' : '')
      + (r.parentNote ? '<p class="bp__coach-parent"><b>For parents:</b> ' + esc(r.parentNote) + '</p>' : '');
    head.insertAdjacentElement('afterend', div);
  }).catch(function () {});
}
